package com.marinainsaurralde.plango;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.marinainsaurralde.plango.model.*;import java.text.SimpleDateFormat;import java.util.*;
public class DetalleConsultaActivity extends AppCompatActivity{public static final String EXTRA="consulta";protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detalle_consulta);findViewById(R.id.buttonBackQuery).setOnClickListener(v->finish());ConsultaHistorial c=(ConsultaHistorial)getIntent().getSerializableExtra(EXTRA);if(c==null){finish();return;}SimpleDateFormat f=new SimpleDateFormat("d MMM yyyy, HH:mm",new Locale("es","ES"));f.setTimeZone(TimeZone.getTimeZone("Europe/Madrid"));set(R.id.textQueryDetailDate,c.fechaConsulta==null?"—":f.format(c.fechaConsulta));set(R.id.textQueryDetailTotals,getString(R.string.history_detail_totals,c.totalEventos,c.totalGratuitos,c.totalPago,c.totalSinInformacion));fill((LinearLayout)findViewById(R.id.layoutDistrictStats),c.eventosPorDistrito);fill((LinearLayout)findViewById(R.id.layoutTypeStats),c.eventosPorTipo);LinearLayout sample=findViewById(R.id.layoutSample);for(MuestraEvento e:c.muestraEventos)add(sample,(e.titulo==null?getString(R.string.event_without_title):e.titulo)+(e.distrito==null?"":" · "+e.distrito));}private void fill(LinearLayout l,Map<String,Integer>m){if(m.isEmpty())add(l,getString(R.string.no_data));else m.forEach((k,v)->add(l,k+": "+v));}private void add(LinearLayout l,String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(15);v.setTextColor(getColor(R.color.plango_text));v.setPadding(0,8,0,8);l.addView(v);}private void set(int id,String s){((TextView)findViewById(id)).setText(s);}}
